const prisma = new PrismaClient();
const app = express();

// Prisma middleware only intercepting basic CRUD actions
prisma.$use(async (params, next) => {
  if (params.model === 'InventoryAudit' && ['findFirst', 'findMany'].includes(params.action)) {
    params.args.where = {
      ...params.args.where,
      warehouseId: params.args.warehouseId
    };
  }
  return next(params);
});

