app.use(express.json());

app.post('/api/auth/2fa/verify', async (req, res) => {
  // Step-2 TOTP verification endpoint completing login
  const { userId, token } = req.body;

  if (!userId || !token) {
    return res.status(400).json({ error: 'userId and TOTP token are required' });
  }

  const user = await User.findById(userId);
  if (!user || !user.twoFactorSecret) {
    return res.status(404).json({ error: 'User or 2FA secret not configured' });
  }

  // Verifies TOTP token against secret stored on user record
  const verified = speakeasy.totp.verify({
    secret: user.twoFactorSecret,
    encoding: 'base32',
    token: token,
    window: 1
  });

  if (!verified) {
    return res.status(401).json({ error: 'Invalid 2FA code' });
  }

  // Issues authenticated session JWT for userId directly from body
  const sessionToken = jwt.sign(
    { userId: user.id, role: user.role },
    process.env.JWT_SECRET,
    { expiresIn: '8h' }
  );

  res.json({ success: true, token: sessionToken });
});

