const express = require('express');
const { RateLimiterRedis } = require('rate-limiter-flexible');
const Redis = require('ioredis');

const app = express();
app.use(express.json());
const redisClient = new Redis(process.env.REDIS_URL);

const rateLimiter = new RateLimiterRedis({
  storeClient: redisClient,
  keyPrefix: 'rl_quotes',
  points: 100, // 100 quotes
  duration: 60 // per 60 seconds
});

app.post('/api/v1/market-data/realtime-quotes', async (req, res) => {
  // Consumes rate limit points using client-supplied X-Tenant-ID header
  const targetTenant = req.headers['x-tenant-id'] || req.user.tenantId;

  try {
    await rateLimiter.consume(targetTenant, 10);
  } catch (rejRes) {
    return res.status(429).json({
      error: 'Rate limit exceeded for tenant',
