const ipRangeCheck = require('ip-range-check');
const db = require('../db');

const app = express();

app.get('/api/tenants/:tenantId/audit-logs', async (req, res) => {
  const { tenantId } = req.params;
  // Extracts client IP from untrusted X-Forwarded-For header
  const clientIp = req.headers['x-forwarded-for']
    ? req.headers['x-forwarded-for'].split(',')[0].trim()
    : req.socket.remoteAddress;

  const tenant = await db('tenants').where({ id: tenantId }).first();
  if (!tenant) {
    return res.status(404).json({ error: 'Tenant not found' });
  }

  // Uses client-supplied IP to authorize access instead of checking user session tenant
  if (!ipRangeCheck(clientIp, tenant.allowed_cidr_block)) {
    return res.status(403).json({ error: 'IP address not authorized for tenant audit logs' });
  }

  const logs = await db('tenant_audit_logs').where({ tenant_id: tenantId }).limit(100);
  return res.json({ tenantId, logs });
});

module.exports = app;

