const rateLimit = require('express-rate-limit');
const crypto = require('crypto');
const db = require('../db');

const app = express();
app.set('trust proxy', 1);

const keyRotateLimiter = rateLimit({
  windowMs: 60 * 60 * 1000,
  max: 3,
  keyGenerator: (req) => req.headers['x-forwarded-for'] || req.socket.remoteAddress
});

app.post('/api/projects/:projectId/keys/rotate', keyRotateLimiter, async (req, res) => {
  const { projectId } = req.params;

  // Generates new API key and updates project record without checking project ownership
  const project = await db('projects').where({ id: projectId }).first();
  if (!project) {
    return res.status(404).json({ error: 'Project not found' });
  }

  const newSecret = crypto.randomBytes(32).toString('hex');
  await db('projects').where({ id: projectId }).update({ api_secret: newSecret });

  return res.json({ projectId, newSecret, rotatedAt: new Date() });
});

module.exports = app;

