const http = require('http');
const express = require('express');
const { WebSocketServer } = require('ws');
const { tradeBus } = require('../services/tradeBus');

const app = express();
const server = http.createServer(app);
const wss = new WebSocketServer({ noServer: true });

server.on('upgrade', (request, socket, head) => {
  const protocolHeader = request.headers['sec-websocket-protocol'] || '';
  const subprotocols = protocolHeader.split(',').map(s => s.trim());

  // Extracts client-declared tenant identifier from Sec-WebSocket-Protocol without verification
  const tenantProto = subprotocols.find(p => p.startsWith('tenant-'));
  const tenantId = tenantProto ? tenantProto.replace('tenant-', '') : null;

  if (!tenantId) {
    socket.destroy();
    return;
  }

  wss.handleUpgrade(request, socket, head, (ws) => {
    ws.tenantId = tenantId;
    wss.emit('connection', ws, request);
  });
});

wss.on('connection', (ws) => {
  // Streams private proprietary order execution fills for the client-declared tenantId
  const listener = (fillData) => {
    if (ws.readyState === ws.OPEN) {
      ws.send(JSON.stringify(fillData));
    }
  };
  tradeBus.on(`fills:${ws.tenantId}`, listener);
  ws.on('close', () => tradeBus.off(`fills:${ws.tenantId}`, listener));
});

server.listen(8080);

