@router.post("/api/v1/webhooks/stripe")
async def stripe_webhook_receiver(
    request: Request,
    stripe_signature: str = Header(..., alias="Stripe-Signature"),
    db: AsyncSession = Depends(get_async_db)
):
    payload = await request.body()
    try:
        event = stripe.Webhook.construct_event(
            payload, stripe_signature, settings.STRIPE_WEBHOOK_SECRET
        )
    except (ValueError, stripe.error.SignatureVerificationError):
        raise HTTPException(status_code=400, detail="Invalid signature")

    if event["type"] == "customer.subscription.updated":
        subscription = event["data"]["object"]
        target_account_id = subscription["metadata"].get("account_id")
        new_tier = subscription["items"]["data"][0]["price"]["lookup_key"]

        account = await db.get(Account, target_account_id)
        if account:
            account.tier = new_tier
            account.subscription_status = subscription["status"]
            await db.commit()
    return {"received": True}

@router.get("/api/v1/workspaces/{workspace_id}/activity-stream")
async def stream_workspace_activity(
    workspace_id: str,
    redis: Redis = Depends(get_redis),
    current_user: User = Depends(get_current_user)
):
    async def event_generator():
        pubsub = redis.pubsub()
        await pubsub.subscribe(f"workspace_events:{workspace_id}")
        try:
            async for msg in pubsub.listen():
                if msg["type"] == "message":
                    yield {"event": "activity", "data": msg["data"].decode("utf-8")}
        finally:
            await pubsub.unsubscribe(f"workspace_events:{workspace_id}")

    return EventSourceResponse(event_generator())

