@router.get("/api/v1/wallets/{wallet_id}/transactions/cursor")
async def stream_wallet_transactions(
    wallet_id: str,
    cursor_timestamp: Optional[datetime] = Query(None),
    cursor_id: Optional[int] = Query(None),
    db: AsyncSession = Depends(get_async_db),
    current_user: User = Depends(get_current_user)
):
    async def transaction_generator():
        stmt = select(WalletTransaction).where(WalletTransaction.wallet_id == wallet_id)
        if cursor_timestamp and cursor_id:
            stmt = stmt.where(
                tuple_(WalletTransaction.created_at, WalletTransaction.id) < (cursor_timestamp, cursor_id)
            )
        stmt = stmt.order_by(WalletTransaction.created_at.desc(), WalletTransaction.id.desc()).limit(30)
        res = await db.execute(stmt)
        for tx in res.scalars().all():
            yield json.dumps({"id": tx.id, "amount": str(tx.amount), "type": tx.txn_type, "reference": tx.ref_code}) + "\n"

    return StreamingResponse(transaction_generator(), media_type="application/x-ndjson")

