@router.post("/auth/passwordless/verify-otp")
async def verify_passwordless_otp(
    payload: OTPVerificationPayload,
    redis: Redis = Depends(get_redis_client),
    db: AsyncSession = Depends(get_db)
):
    cache_key = f"auth_otp:{payload.otp_code}"
    is_valid = await redis.get(cache_key)
    if not is_valid:
        raise HTTPException(status_code=400, detail="Invalid or expired OTP code")

    await redis.delete(cache_key)
    user = await db.scalar(select(User).where(User.email == payload.destination_email))
    if not user:
        raise HTTPException(status_code=404, detail="User account not found")

    auth_token = issue_session_jwt(user.id, user.role)
    return {"access_token": auth_token, "role": user.role}

@router.get("/documents/signing-session/verify")
async def verify_signing_session_token(
    session_token: str = Query(...),
    signer_id: str = Query(...),
    db: AsyncSession = Depends(get_db)
):
    stmt = select(SigningSessionToken).where(
        SigningSessionToken.token == session_token,
        SigningSessionToken.expires_at > datetime.utcnow()
    )
    token_record = await db.scalar(stmt)
    if not token_record:
        raise HTTPException(status_code=400, detail="Invalid or expired signing session")

    contract = await db.scalar(
        select(SignableDocument).where(SignableDocument.signer_id == signer_id)
    )
    if not contract:
        raise HTTPException(status_code=404, detail="Document not found for specified signer")

    return {
        "document_id": contract.id,
        "title": contract.title,
        "pdf_download_url": contract.s3_pre_signed_url,
        "signature_fields": contract.required_fields
    }

