@router.post("/sso/saml/slo")
async def saml_single_logout(
    request: Request,
    session_cache: Redis = Depends(get_redis_client)
):
    req_data = await prepare_fastapi_request_for_saml(request)
    auth = OneLogin_Saml2_Auth(req_data, get_global_saml_settings())
    url = auth.process_slo(keep_local_session=True)

    name_id = auth.get_nameid()
    if name_id:
        pattern = f"session:*:{name_id}:*"
        keys = await session_cache.keys(pattern)
        if keys:
            await session_cache.delete(*keys)

    return RedirectResponse(url or "/login")

@router.get("/sso/saml/tenants/{tenant_id}/sp-metadata.xml")
async def get_tenant_sp_metadata(
    tenant_id: str,
    db: AsyncSession = Depends(get_db)
):
    tenant_config = await db.scalar(
        select(TenantSAMLConfig).where(TenantSAMLConfig.tenant_id == tenant_id)
    )
    if not tenant_config:
        raise HTTPException(status_code=404, detail="SAML configuration not found")

    settings = OneLogin_Saml2_Settings(tenant_config.saml_settings_dict)
    metadata = settings.get_sp_metadata()
    errors = settings.validate_metadata(metadata)
    if errors:
        raise HTTPException(status_code=500, detail="Metadata validation failed")

    return Response(content=metadata, media_type="application/xml")

@router.post("/sso/saml/exchange-token")
async def exchange_saml_assertion_for_token(
    payload: SAMLExchangePayload,
    db: AsyncSession = Depends(get_db)
):
    auth = OneLogin_Saml2_Auth(payload.saml_request_data, get_global_saml_settings())
    auth.process_response()

    if auth.get_errors():
        raise HTTPException(status_code=401, detail="SAML verification failed")

    user_email = auth.get_nameid()
    user = await db.scalar(select(User).where(User.email == user_email))
    if not user:
        raise HTTPException(status_code=404, detail="User account not found")

    target_tenant = payload.audience_tenant or user.default_tenant
    api_token = generate_scoped_jwt(user.id, target_tenant)
    return {"token": api_token, "audience": target_tenant}

