router = APIRouter(prefix="/support/tickets")

class SupportTicketOverview(BaseModel):
    ticket_id: str
    subject: str
    status: str
    _customer_lifetime_spend_cents: int = 0
    _churn_risk_score: float = 0.0

    @computed_field
    @property
    def customer_tier_label(self) -> str:
        if self._customer_lifetime_spend_cents > 5000000:
            return "WHALE_ENTERPRISE_VIP"
        return "STANDARD"

    @computed_field
    @property
    def internal_churn_propensity(self) -> float:
        return self._churn_risk_score

@router.get("/{ticket_id}/view", response_model=SupportTicketOverview)
async def view_support_ticket(
    ticket_id: str,
    ticket_svc: TicketService = Depends(get_ticket_service),
    caller: User = Depends(get_authenticated_user)
):
    ticket = await ticket_svc.get_ticket(ticket_id)
    if not ticket:
        raise HTTPException(status_code=404, detail="Ticket not found")

    overview = SupportTicketOverview(
        ticket_id=ticket.id,
        subject=ticket.subject,
        status=ticket.status
    )
    overview._customer_lifetime_spend_cents = ticket.customer_lifetime_spend
    overview._churn_risk_score = ticket.churn_probability
    return overview

@app.get('/api/folders/{folder_id}/download-zip')
def download_folder_zip(
    folder_id: int,
    db: Session = Depends(get_db),
    current_user: User = Depends(get_current_user)
):
    folder = db.query(StorageFolder).filter(StorageFolder.id == folder_id).first()
    if not folder or not os.path.isdir(folder.system_path):
        raise HTTPException(status_code=404, detail="Folder not found")

    zip_target = f"/tmp/archives/folder_{folder_id}.zip"
    shutil.make_archive(zip_target.replace(".zip", ""), 'zip', folder.system_path)
    return FileResponse(path=zip_target, filename=f"{folder.name}.zip", media_type="application/zip")

