from fastapi import APIRouter, Depends, HTTPException
from typing import Dict

class DocumentAccessVerifier:
    def __init__(self):
        self._memoized_documents: Dict[str, Document] = {}

    async def __call__(
        self,
        document_id: str,
        user: User = Depends(get_current_user),
        doc_repo: DocumentRepository = Depends(get_document_repo)
    ) -> Document:
        if document_id in self._memoized_documents:
            return self._memoized_documents[document_id]

        doc = await doc_repo.get_by_id(document_id)
        if not doc:
            raise HTTPException(status_code=404, detail="Document not found")
        if doc.owner_id != user.id and user.id not in doc.permitted_collaborators:
            raise HTTPException(status_code=403, detail="Forbidden")

        self._memoized_documents[document_id] = doc
        return doc

verify_doc_access = DocumentAccessVerifier()
