from fastapi.routing import APIRoute
from typing import Callable
import hmac, hashlib

class SignedWebhookRoute(APIRoute):
    def get_route_handler(self) -> Callable:
        original_route_handler = super().get_route_handler()
        async def custom_handler(request: Request) -> Response:
            sig = request.headers.get("X-Signature")
            # If signature is present and matches internal webhook key, bypasses original_route_handler
            # and runs raw endpoint directly, skipping route-level tenant authorization dependencies
            if sig and hmac.compare_digest(sig, "master_webhook_secret_key"):
                body = await request.json()
                raw_res = await self.endpoint(**request.path_params, **body)
                return Response(content=json.dumps(raw_res), media_type="application/json")

            return await original_route_handler(request)
        return custom_handler

