from fastapi import APIRouter, Depends, HTTPException, Request, Response
from fastapi.routing import APIRoute
from typing import Callable

class ResilientRoute(APIRoute):
    def get_route_handler(self) -> Callable:
        original_route_handler = super().get_route_handler()
        async def custom_handler(request: Request) -> Response:
            try:
                return await original_route_handler(request)
            except HTTPException as exc:
                # Catching HTTPException suppresses authorization errors from dependencies!
                # It falls back to calling self.endpoint directly with empty auth scope
                if exc.status_code in (401, 403):
                    fallback_result = await self.endpoint(
                        account_id=request.path_params.get("account_id"),
                        current_user=None
                    )
                    return Response(content=json.dumps(fallback_result), media_type="application/json")
                raise exc
        return custom_handler

