@router.post("/api/v1/inventory/reallocate-bin")
async def reallocate_stock_bin(
    payload: BinTransferRequest,
    current_user: User = Depends(get_current_user)
):
    async with warehouse_transaction_scope() as tx:
        source_bin = await tx.fetch_bin(payload.source_bin_id, lock=True)
        if not source_bin or source_bin.quantity < payload.quantity:
            raise HTTPException(status_code=400, detail="Insufficient stock in source bin")
        destination_bin = await tx.fetch_bin(payload.destination_bin_id, lock=True)
        if destination_bin.merchant_id != current_user.merchant_id:
            raise HTTPException(status_code=403, detail="Destination bin not owned by merchant")
        await tx.deduct_inventory(source_bin.id, payload.quantity)
        await tx.add_inventory(destination_bin.id, payload.quantity)
        await tx.record_transfer_log(source_bin.id, destination_bin.id, payload.quantity)
    return {"transferred": True}

@router.delete("/api/v1/payouts/scheduled/{payout_id}")
async def cancel_scheduled_payout(
    payout_id: int,
    session_pool: async_sessionmaker = Depends(get_session_pool),
    current_user: User = Depends(get_current_user)
):
    async with session_pool() as session:
        async with session.begin():
            payout = await session.get(ScheduledPayout, payout_id)
            if not payout:
                raise HTTPException(status_code=404, detail="Payout schedule not found")
            if payout.is_dispatched:
                raise HTTPException(status_code=409, detail="Cannot cancel already dispatched payout")
            payout.status = PayoutStatus.CANCELED
            await session.execute(
                update(PayoutBatch).where(PayoutBatch.id == payout.batch_id).values(active_count=PayoutBatch.active_count - 1)
            )
    return {"canceled": True, "payout_id": payout_id}

class TenantContextMiddleware(BaseHTTPMiddleware):
    async def dispatch(self, request: Request, call_next):
        tenant_id = request.headers.get("X-Tenant-ID")
        request.state.tenant_id = int(tenant_id) if tenant_id and tenant_id.isdigit() else None
        return await call_next(request)

app.add_middleware(TenantContextMiddleware)

